<?php
namespace App\Http\Controllers;
use App\Models\Classroom; use App\Models\User; use App\Models\Grade; use App\Models\ReportCard; use App\Models\AcademicYear; use App\Models\Semester; use Illuminate\Http\Request;
class ReportCardController extends Controller {
 private function assertHomeroom(Classroom $c): void { $u=auth()->user(); abort_unless(in_array($u->role,['admin','super_admin'],true)||($u->role==='guru' && (int)$c->homeroom_teacher_id===(int)$u->id),403,'Hanya wali kelas yang ditugaskan dapat mengolah rapor kelas ini.'); }
 public function index(){ $u=auth()->user(); $q=Classroom::with('homeroomTeacher')->orderBy('name'); if($u->role==='guru') $q->where('homeroom_teacher_id',$u->id); else abort_unless(in_array($u->role,['admin','super_admin'],true),403); $classes=$q->get(); $years=AcademicYear::orderByDesc('id')->get(); $semesters=Semester::with('academicYear')->orderBy('id')->get(); return view('reports.process_index',compact('classes','years','semesters')); }
 public function classroom(Request $r, Classroom $classroom){ $this->assertHomeroom($classroom); $d=$r->validate(['academic_year_id'=>'required|exists:academic_years,id','semester_id'=>'required|exists:semesters,id']); $students=$classroom->students()->orderBy('name')->get(); $cards=ReportCard::where('classroom_id',$classroom->id)->where('academic_year_id',$d['academic_year_id'])->where('semester_id',$d['semester_id'])->get()->keyBy('student_id'); $gradeCounts=Grade::where('classroom_id',$classroom->id)->where('academic_year_id',$d['academic_year_id'])->where('semester_id',$d['semester_id'])->where('status','published')->selectRaw('student_id,count(*) as total')->groupBy('student_id')->pluck('total','student_id'); return view('reports.process_classroom',compact('classroom','students','cards','gradeCounts','d')); }
 public function edit(Request $r, User $student){ abort_unless($student->role==='siswa',404); $classroom=$student->classroom; abort_unless($classroom,404); $this->assertHomeroom($classroom); $d=$r->validate(['academic_year_id'=>'required|exists:academic_years,id','semester_id'=>'required|exists:semesters,id']); $grades=Grade::with('subject')->where('student_id',$student->id)->where('academic_year_id',$d['academic_year_id'])->where('semester_id',$d['semester_id'])->where('status','published')->orderBy('subject_id')->get(); $card=ReportCard::firstOrNew(['student_id'=>$student->id,'academic_year_id'=>$d['academic_year_id'],'semester_id'=>$d['semester_id']]); return view('reports.process_form',compact('student','classroom','grades','card','d')); }
 public function save(Request $r, User $student){ abort_unless($student->role==='siswa' && $student->classroom,404); $this->assertHomeroom($student->classroom); $d=$r->validate(['academic_year_id'=>'required|exists:academic_years,id','semester_id'=>'required|exists:semesters,id','skill_score'=>'required|numeric|between:0,100','attitude_score'=>'required|numeric|between:0,100','motivation'=>'required|string|max:2000','suggestion'=>'nullable|string|max:2000']); $ready=Grade::where('student_id',$student->id)->where('academic_year_id',$d['academic_year_id'])->where('semester_id',$d['semester_id'])->where('status','published')->exists(); abort_unless($ready,422,'Belum ada nilai mata pelajaran yang diinput dan dipublikasikan guru.'); $card=ReportCard::firstOrNew(['student_id'=>$student->id,'academic_year_id'=>$d['academic_year_id'],'semester_id'=>$d['semester_id']]); if($card->exists && in_array($card->status,['submitted','approved'])) abort(422,'Pengolahan sudah dikirim atau disetujui.'); $card->fill($d+['classroom_id'=>$student->classroom_id,'homeroom_teacher_id'=>($student->classroom->homeroom_teacher_id ?: auth()->id()),'status'=>'draft','admin_note'=>null]); $card->save(); return back()->with('success','Pengolahan rapor berhasil disimpan sebagai draft.'); }
 public function submit(Request $r, ReportCard $reportCard){ $c=$reportCard->classroom; $this->assertHomeroom($c); abort_unless(in_array($reportCard->status,['draft','revision']),422); $hasGrades=Grade::where('student_id',$reportCard->student_id)->where('academic_year_id',$reportCard->academic_year_id)->where('semester_id',$reportCard->semester_id)->where('status','published')->exists(); abort_unless($hasGrades,422,'Nilai mapel belum disetujui admin.'); $reportCard->forceFill(['status'=>'submitted','submitted_at'=>now(),'admin_note'=>null])->save(); return redirect()->route('report-cards.classroom',[$c->id,'academic_year_id'=>$reportCard->academic_year_id,'semester_id'=>$reportCard->semester_id])->with('success','Pengolahan rapor berhasil dikirim. Sekarang muncul pada dashboard admin untuk divalidasi.'); }
}
